-- ========================= dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event =========================
-- source     : NonlifePolicySalesCockpitSyncEvent_v1_1.avsc
-- key schema : NonlifePolicySalesCockpitTopicKeySchema_v1.avsc
-- system     : HUGO   load: Kafka sync   grain: One row per Kafka message
CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event (
    sales_id                                         STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       NOT NULL  COMMENT 'Unikátní identifikátor kalkulace smlouvy nebo pojištění, v kontextu prodeje. Klíč Kafka zprávy.',
    nonlife_policy_basic_premium                     DECIMAL(38,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Castka reprezentujici pojistnika v penezich (Kc).',
    nonlife_policy_case_number                       STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Cislo obchodniho pripadu.',
    nonlife_policy_catalogue_nonlife_product_bundle  STRUCT<`code`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       NOT NULL  COMMENT 'Katalogová definice balíčku produktů z pohledu controllingu. Controlling používá jednotný katalog pro celou společnost.',
    nonlife_policy_change_effective_date             DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Datum ucinnosti zmeny.',
    nonlife_policy_created_on                        DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         NOT NULL  COMMENT 'Datum, kdy byla smlouva nebo pojisteni vytvoreno.',
    nonlife_policy_last_updated_by                   STRUCT<`domain_login`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               NOT NULL  COMMENT 'Uzivatel systemu nebo aplikace',
    nonlife_policy_nonlife_mta_realizators           ARRAY<STRUCT<`agent`: STRUCT<`domain_login`: STRING>, `agent_personnel_relationship`: STRUCT<`number`: BIGINT>, `agent_relationship`: STRUCT<`id`: BIGINT>, `roles`: ARRAY<STRING>, `sub_agent`: STRUCT<`domain_login`: STRING>>>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             COMMENT 'Informace o agentovi v kontextu smlouvy (nebo pojisteni) nebo jeho verzi. Napr. stejny agent muze mit vice vstupu do jedne smlouvy (nebo pojisteni), protoze muze byt realizator vice zmen smlouvy.',
    nonlife_policy_nonlife_policy_acquirers          ARRAY<STRUCT<`agent`: STRUCT<`domain_login`: STRING>, `agent_personnel_relationship`: STRUCT<`number`: BIGINT>, `agent_relationship`: STRUCT<`id`: BIGINT>, `roles`: ARRAY<STRING>, `sub_agent`: STRUCT<`domain_login`: STRING>>>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Informace o agentovi v kontextu smlouvy (nebo pojisteni) nebo jeho verzi. Napr. stejny agent muze mit vice vstupu do jedne smlouvy (nebo pojisteni), protoze muze byt realizator vice zmen smlouvy.',
    nonlife_policy_nonlife_product_instances         ARRAY<STRUCT<`agreement_line`: STRUCT<`number`: BIGINT>, `catalogue_product`: STRUCT<`code`: INT>, `property_locations`: ARRAY<STRUCT<`address_point`: STRUCT<`evidence_number`: STRING, `land_register_number`: STRING, `municipality`: STRING, `ruian_address_point`: STRUCT<`code`: BIGINT>, `street`: STRING, `street_number`: STRING, `zip_code`: STRING>, `cadastral_plot`: STRUCT<`cadastral_area`: STRUCT<`id`: BIGINT, `name`: STRING>, `number`: STRING, `sub_number`: STRING>>>, `valid_from`: DATE, `valid_to`: DATE, `vehicles`: ARRAY<STRUCT<`brand`: STRING, `engine`: STRUCT<`displacement`: INT, `power`: INT>, `identification_number`: STRING, `registration_number`: STRING, `type`: STRING>>, `yearly_premium`: DECIMAL(38,2)>>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         NOT NULL  COMMENT 'Prehledove informace ohledne nezivotniho produktu pojisteni (jeho instance) partnera s GCZ skupinou.',
    nonlife_policy_version                           STRUCT<`sales_id`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   NOT NULL  COMMENT 'Verze a verzovane vlastnosti pojistne smlouvy.',
    nonlife_policy_application                       STRUCT<`id`: INT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Systém nebo aplikace jako definice, nikoliv konkrétní instance. Například TIA, HUGO nebo LISA2.',
    nonlife_policy_company                           STRUCT<`id`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         NOT NULL  COMMENT 'Pravnicka osoba (pravnicka osoba), ktera patri do skupiny GCZ, napr. GCP, GCD.',
    nonlife_policy_data_updated_at                   TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    NOT NULL  COMMENT 'Technický atribut s datem a časem, od kterého byla data smlouvy aktualizována z core systému.',
    nonlife_policy_number                            BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Unikatni a verejny identifikator (Cislo smlouvy).',
    nonlife_policy_party_in_policy                   STRUCT<`addresses`: STRUCT<`correspondence`: STRUCT<`additional_delivery_instruction`: STRING, `country`: STRING, `evidence_number`: STRING, `land_register_number`: STRING, `municipality`: STRING, `street`: STRING, `street_number`: STRING, `zip_code`: STRING>>, `electronic_contacts`: STRUCT<`email`: STRUCT<`email_address`: STRING>, `fixed_line`: STRUCT<`structured`: STRUCT<`international_prefix`: INT, `national_number`: STRING>>, `mobile_phone`: STRUCT<`structured`: STRUCT<`international_prefix`: INT, `national_number`: STRING>>>, `party_legal_type_choice`: STRUCT<`juridical_organization`: STRUCT<`country_of_registration`: STRING, `identification_number`: STRING, `name`: STRING, `registered_in`: STRING, `registered_with`: STRING, `party_id`: STRING>, `natural_person`: STRUCT<`academic_title_prefix`: STRING, `academic_title_suffix`: STRING, `birth_date`: DATE, `birth_number`: STRING, `citizenship`: STRING, `first_name`: STRING, `sex`: INT, `surname`: STRING, `party_id`: STRING>, `self_employed`: STRUCT<`academic_title_prefix`: STRING, `academic_title_suffix`: STRING, `birth_date`: DATE, `birth_number`: STRING, `citizenship`: STRING, `first_name`: STRING, `juridical_person_info`: STRUCT<`country_of_registration`: STRING, `identification_number`: STRING>, `name`: STRING, `registered`: BOOLEAN, `registered_in`: STRING, `registered_with`: STRING, `surname`: STRING, `party_id`: STRING>>> NOT NULL  COMMENT 'Informace o partnerovi, jeho osobni a byznys informace. Informace o parnerovi ve specifikem kontextu, ktery je z jine domeny. Informace o partnerovy, ktere jsou platne jen v kontextu urcite smlouvy nebo pojisteni.',
    nonlife_policy_payment_activation_deadline       DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Datum, do kterého musí být připsána první platba pojistného, jinak smlouva nenabude platnosti.',
    nonlife_policy_payment_frequency                 INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           COMMENT 'Frekvence s jakou se musi platit pojistne (mesicni, rocni). Codelist: KCC.ZpusPlac.',
    nonlife_policy_status                            INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          NOT NULL  COMMENT 'Stav pojiseni nebo smlouvy. Codelist: KCC.StavPojSml.',
    nonlife_policy_valid_from                        DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Datum, od kterého je instance produktu platná.',
    nonlife_policy_valid_to                          DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Datum, do kterého je instance produktu platná.',
    nonlife_policy_yearly_premium                    DECIMAL(38,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Mnozstvi penez, ktere musi partner platit za jeden rok pojisteni.',
    __message_valid_flag                             BOOLEAN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      NOT NULL  COMMENT 'TRUE, když zpráva odpovídala deklarované struktuře sloupců. Protože jsou strukturní sloupce typované, Databricks při neshodě typu nespadne, ale uloží NULL, takže tento příznak a __rescued_data jsou jediný způsob, jak se neshoda projeví. Řádek se i tak uloží, v bronze se nic neodmítá.',
    __message_error_desc                             STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Co konkrétně nesedí, pokud je __message_valid_flag FALSE. Obsahuje cestu k položce a důvod, například neočekávané pole, chybějící povinné pole nebo hodnotu nesplňující deklarovaný pattern.',
    __rescued_data                                   STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Pole, která se do deklarované struktury sloupců nevešla, včetně hodnot, serializovaná jako JSON. U typovaných strukturních sloupců je to jediné místo, kde nové nebo přetypované pole přežije; bez něj by se hodnota tiše ztratila nebo znulovala.',
    __schema_version_id                              INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           COMMENT 'Identifikátor schématu z schema registry, kterým byla zpráva zapsána. Čte se z obálky zprávy, takže je znám i u zprávy, která neprojde validací.',
    __trace_id                                       STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Unikátní identifikátor transakce. Jedná se o identifikátor konkrétní transakce.',
    __msg_id                                         STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Unikátní identifikátor zprávy. Jedná se o identifikátor konkrétního volání.',
    __source_eap_id                                  STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Identifikátor zdrojového systému z aplikace EAP (eapId)',
    __user_domain_login                              STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Uživatelské jméno (s doménou)',
    __kafka_partition                                INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           COMMENT 'Identifikátor Kafka partition, ze které byla zpráva načtena. Slouží k jednoznačné identifikaci původu zprávy v rámci topicu a společně s offsetem umožňuje určit její přesné pořadí v dané partition.',
    __kafka_offset                                   BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Jedinečná pozice zprávy v rámci Kafka partition. Offset je průběžně rostoucí číslo přidělené brokerem Kafka při uložení zprávy a používá se pro sledování zpracování, deduplikaci a obnovu čtení dat.',
    __kafka_timestamp                                TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     COMMENT 'Kafka - časové razítko, kdy zpráva přišla.',
    __source_system                                  STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Zdrojový systém',
    __load_timestamp                                 TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name                                      STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Jméno zdrojového souboru',
    __file_path                                      STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Cesta ke zdrojovému souboru',
    CONSTRAINT pk_nonlife_policy_sales_cockpit_sync_event PRIMARY KEY (sales_id) NOT ENFORCED
)
USING DELTA
COMMENT 'Stavy před uzavřením smlouvy a uzavřené smlouvy neživotního pojištění ze systému HUGO. Číslo smlouvy je nepovinné, dokud ho nepřidělí TIA. Rámcová smlouva se pozná podle catalogueNonlifeProductBundle.code = FA, podsmlouvy na tomto topiku nechodí.'
CLUSTER BY (sales_id)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'HUGO',
    'source.object'              = 'NonlifePolicySalesCockpitSyncEvent_v1_1.avsc',
    'load.pattern'               = 'Kafka sync'
);
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event SET TAGS ('description_en' = 'Pre-contract states and concluded contracts for non-life insurance from HUGO. The contract number is optional until TIA assigns it. A framework contract is identified by catalogueNonlifeProductBundle.code = FA; sub-contracts never occur on this topic.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN sales_id SET TAGS ('description_en' = 'Unique identifier of the policy or insurance calculation in the context of sales. Kafka message key.');
