ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_last_updated_by SET TAGS ('description_en' = 'An identity created for a person in a computer or computing system');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_nonlife_mta_realizators SET TAGS ('description_en' = 'Information about agent in context of particular policy (or insurance) or its version. I.e., the same agent can have multiple entries on one policy/insurance because he can be realizator of multiple MTAs');
