ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_nonlife_product_instances SET TAGS ('description_en' = 'Overview information about nonlife insurance product (instance) of partner with GCZ group company');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_version SET TAGS ('description_en' = 'Version and versioned properties of nonlife policy');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_application SET TAGS ('description_en' = 'System/application (definition, not particular instance). E.g., TIA, HUGO, LISA2');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_company SET TAGS ('description_en' = 'Juridical person (legal entity) that belongs to GCZ group, e.g., GCP, GCD. Company that is closely connected to GCZ');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_data_updated_at SET TAGS ('description_en' = 'Technical attribute that represents date and time from which PolicyOrInsurance data were updated from CORE system. Technical attribute that represents date and time from which PolicyOrInsurance data were updated from CORE system. This is metadata, this has no business meaning');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_number SET TAGS ('description_en' = 'Unique and public identifier');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_party_in_policy SET TAGS ('description_en' = 'Party is real world person or its suborganization that can be interpreted as client or client related. Typically, it is person or its suborganization that has at least one role on policy as policyholder or insured or at least one role on claim as claimant. Information about party in one particular context. Context re predefined (policy, claim, client zone,...). Context is object from different domain. That means that information about party in context is owned by different domain and this is only copy of it. E.g. party in policy or party in claim. Information about party that is valid only in context of particular insurance or policy');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_payment_activation_deadline SET TAGS ('description_en' = 'Date until which first policy premium payment must be credited to a policy or insurance or policy or insurance will not be valid');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_payment_frequency SET TAGS ('description_en' = 'Frequency of premium payments, e.g., monthly, yearly');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_status SET TAGS ('description_en' = 'Insurance\'s or insurance contract\'s status, e.g., active, terminated');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_valid_from SET TAGS ('description_en' = 'Date from which product instance is valid');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_valid_to SET TAGS ('description_en' = 'Date until which product instance is valid');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN nonlife_policy_yearly_premium SET TAGS ('description_en' = 'Amount of money that partner is obliged to pay for one year of insurance');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __message_valid_flag SET TAGS ('description_en' = 'TRUE when the message matched the declared column structure. Because the structural columns are typed, Databricks turns a type mismatch into NULL instead of failing, so this flag and __rescued_data are the only way a mismatch becomes visible. The row is still landed; nothing is rejected in bronze.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __message_error_desc SET TAGS ('description_en' = 'What exactly does not match, where __message_valid_flag is FALSE. Holds the field path and the reason, for example an unexpected field, a missing mandatory field or a value that does not satisfy the declared pattern.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __rescued_data SET TAGS ('description_en' = 'Fields that did not fit the declared column structure, with their values, serialised as JSON. With typed structural columns this is the only place a new or retyped field survives; without it the value would be silently dropped or nulled.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __schema_version_id SET TAGS ('description_en' = 'Identifier of the schema from the schema registry that the message was written with. Read from the message envelope, so it is known even for a message that fails validation.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __trace_id SET TAGS ('description_en' = 'Unique identifier of the transaction. Identifies one particular transaction.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __msg_id SET TAGS ('description_en' = 'Unique identifier of the message. Identifies one particular call.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __source_eap_id SET TAGS ('description_en' = 'Identifier of the source system taken from the EAP application (eapId).');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __user_domain_login SET TAGS ('description_en' = 'User name including the domain.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __kafka_partition SET TAGS ('description_en' = 'Identifier of the Kafka partition the message was read from. It identifies the origin of the message within the topic and, together with the offset, determines its exact order within that partition.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __kafka_offset SET TAGS ('description_en' = 'Unique position of the message within a Kafka partition. The offset is an increasing number assigned by the Kafka broker when the message is stored and is used for processing tracking, deduplication and read recovery.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __kafka_timestamp SET TAGS ('description_en' = 'Kafka timestamp of when the message arrived.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __source_system SET TAGS ('description_en' = 'Source system.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __load_timestamp SET TAGS ('description_en' = 'Timestamp of when the record was added to the table.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __file_name SET TAGS ('description_en' = 'Name of the source file.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN __file_path SET TAGS ('description_en' = 'Path of the source file.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.nonlife_policy_sales_cockpit_sync_event ALTER COLUMN sales_id SET TAGS ('data_classification' = 'confidential');

-- ========================= dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event =========================
-- source     : LifePolicySalesCockpitSyncEvent_v1_1.avsc
-- key schema : LifePolicySalesCockpitTopicKeySchema_v1.avsc
-- system     : LISA   load: Kafka sync   grain: One row per Kafka message
CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event (
    case_number                          STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                NOT NULL  COMMENT 'Unikátní identifikátor prodejního procesu životní smlouvy. Klíč Kafka zprávy.',
    life_policy_catalogue_life_brand     STRUCT<`id`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   COMMENT 'Zakladni informace o katalogovem life brandu.',
    life_policy_catalogue_product        STRUCT<`code`: INT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    COMMENT 'Katalogová definice produktu z pohledu controllingu. Controlling používá jednotný katalog pro celou společnost.',
    life_policy_life_policy_case         STRUCT<`created_on`: DATE, `number`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          NOT NULL  COMMENT 'Konkrétní byznys proces nebo činnost vztahující se ke smlouvě, kterou organizace sleduje nebo eviduje. Jde o prodejní proces, ať už jde o sjednání nové smlouvy nebo o její změnu.',
    life_policy_life_policy_event        STRUCT<`type`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                NOT NULL  COMMENT 'Událost na životní smlouvě. Může jít o významnou činnost, například vznik smlouvy nebo technickou změnu, ale i o drobnou změnu, například změnu údajů partnera.',
    life_policy_technical_id             STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                NOT NULL  COMMENT 'Identifkator bez byznys vyznamu.',
    life_policy_agents                   ARRAY<STRUCT<`domain_login`: STRING, `external_id`: STRING, `id`: BIGINT>>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Obchodni vztah z organizacniho hlediska s pridelenym "ziskatelskym cislem". Definovano jako agent, kde uzivatel patrici k GCZPerson tohoto agenta ma domenu jinou nez "cpas". ("servis"). Uzivatel systemu nebo aplikace',
    life_policy_application              STRUCT<`id`: INT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     NOT NULL  COMMENT 'Systém nebo aplikace jako definice, nikoliv konkrétní instance. Například TIA, HUGO nebo LISA2.',
    life_policy_company                  STRUCT<`id`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  NOT NULL  COMMENT 'Pravnicka osoba (pravnicka osoba), ktera patri do skupiny GCZ, napr. GCP, GCD.',
    life_policy_data_updated_at          TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             NOT NULL  COMMENT 'Technický atribut s datem a časem, od kterého byla data smlouvy aktualizována z core systému.',
    life_policy_number                   BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Unikatni a verejny identifikator (Cislo smlouvy).',
    life_policy_party_in_policy          STRUCT<`addresses`: STRUCT<`correspondence`: STRUCT<`additional_delivery_instruction`: STRING, `country`: STRING, `evidence_number`: STRING, `land_register_number`: STRING, `municipality`: STRING, `street`: STRING, `street_number`: STRING, `zip_code`: STRING>>, `electronic_contacts`: STRUCT<`email`: STRUCT<`email_address`: STRING>, `mobile_phone`: STRUCT<`phone_number_format_choice`: STRUCT<`international`: STRUCT<`full_number`: STRING>, `structured`: STRUCT<`international_prefix`: INT, `national_number`: STRING>>>>, `party_legal_type_choice`: STRUCT<`juridical_organization`: STRUCT<`country_of_registration`: STRING, `identification_number`: STRING, `name`: STRING, `legal_type`: INT, `party_id`: STRING>, `natural_person`: STRUCT<`academic_title_prefix`: STRING, `academic_title_suffix`: STRING, `birth_date`: DATE, `birth_number`: STRING, `citizenship`: STRING, `first_name`: STRING, `sex`: INT, `surname`: STRING, `legal_type`: INT, `party_id`: STRING>>> NOT NULL  COMMENT 'Informace o partnerovi, jeho osobni a byznys informace. Informace o parnerovi ve specifikem kontextu, ktery je z jine domeny. Informace o partnerovy, ktere jsou platne jen v kontextu urcite smlouvy nebo pojisteni.',
    life_policy_payment_frequency        INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   NOT NULL  COMMENT 'Frekvence s jakou se musi platit pojistne (mesicni, rocni). Codelist: KCC.ZpusPlac.',
    life_policy_period_final_discounted  DECIMAL(38,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Částka pojistného za zvolené období po uplatnění slev.',
    life_policy_status                   INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   NOT NULL  COMMENT 'Stav pojiseni nebo smlouvy. Codelist: KCC.StavPojSml.',
    life_policy_super                    BOOLEAN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                COMMENT 'Příznak, zda jde o rámcovou smlouvu. Ve starém systému nazývaná ramcovka.',
    life_policy_super_policy_reference   STRUCT<`number`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               COMMENT 'Vybrane informace o pojisteni nebo pojistovaci smlouve partnera s GCZ skupinou. Prehledne informace o pojistne ramcove (nebo kvazi-ramcove flotilove) smlouve partnera se spolecnosti skupiny GCZ.',
    life_policy_valid_from               DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   COMMENT 'Datum, od kterého je instance produktu platná.',
    life_policy_valid_to                 DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   COMMENT 'Datum, do kterého je instance produktu platná.',
    life_policy_yearly_premium           DECIMAL(38,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Mnozstvi penez, ktere musi partner platit za jeden rok pojisteni.',
    __message_valid_flag                 BOOLEAN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               NOT NULL  COMMENT 'TRUE, když zpráva odpovídala deklarované struktuře sloupců. Protože jsou strukturní sloupce typované, Databricks při neshodě typu nespadne, ale uloží NULL, takže tento příznak a __rescued_data jsou jediný způsob, jak se neshoda projeví. Řádek se i tak uloží, v bronze se nic neodmítá.',
    __message_error_desc                 STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Co konkrétně nesedí, pokud je __message_valid_flag FALSE. Obsahuje cestu k položce a důvod, například neočekávané pole, chybějící povinné pole nebo hodnotu nesplňující deklarovaný pattern.',
    __rescued_data                       STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Pole, která se do deklarované struktury sloupců nevešla, včetně hodnot, serializovaná jako JSON. U typovaných strukturních sloupců je to jediné místo, kde nové nebo přetypované pole přežije; bez něj by se hodnota tiše ztratila nebo znulovala.',
    __schema_version_id                  INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    COMMENT 'Identifikátor schématu z schema registry, kterým byla zpráva zapsána. Čte se z obálky zprávy, takže je znám i u zprávy, která neprojde validací.',
    __trace_id                           STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Unikátní identifikátor transakce. Jedná se o identifikátor konkrétní transakce.',
    __msg_id                             STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Unikátní identifikátor zprávy. Jedná se o identifikátor konkrétního volání.',
    __source_eap_id                      STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Identifikátor zdrojového systému z aplikace EAP (eapId)',
    __user_domain_login                  STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Uživatelské jméno (s doménou)',
    __kafka_partition                    INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    COMMENT 'Identifikátor Kafka partition, ze které byla zpráva načtena. Slouží k jednoznačné identifikaci původu zprávy v rámci topicu a společně s offsetem umožňuje určit její přesné pořadí v dané partition.',
    __kafka_offset                       BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Jedinečná pozice zprávy v rámci Kafka partition. Offset je průběžně rostoucí číslo přidělené brokerem Kafka při uložení zprávy a používá se pro sledování zpracování, deduplikaci a obnovu čtení dat.',
    __kafka_timestamp                    TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              COMMENT 'Kafka - časové razítko, kdy zpráva přišla.',
    __source_system                      STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Zdrojový systém',
    __load_timestamp                     TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name                          STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Jméno zdrojového souboru',
    __file_path                          STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Cesta ke zdrojovému souboru',
    CONSTRAINT pk_life_policy_sales_cockpit_sync_event PRIMARY KEY (case_number) NOT ENFORCED
)
USING DELTA
COMMENT 'Stavy před uzavřením smlouvy a uzavřené smlouvy životního pojištění ze systému LISA. Číslo smlouvy je nepovinné, dokud ho nepřidělí KDP. Rámcová smlouva má super = true, podsmlouva má vyplněné superPolicyReference.number.'
CLUSTER BY (case_number)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'LISA',
    'source.object'              = 'LifePolicySalesCockpitSyncEvent_v1_1.avsc',
    'load.pattern'               = 'Kafka sync'
);
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event SET TAGS ('description_en' = 'Pre-contract states and concluded contracts for life insurance from LISA. The contract number is optional until KDP assigns it. A framework contract has super = true, a sub-contract has superPolicyReference.number filled.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN case_number SET TAGS ('description_en' = 'Unique identifier of the life policy sale process. Kafka message key.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_catalogue_life_brand SET TAGS ('description_en' = 'Basic information about catalogue life brand');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_catalogue_product SET TAGS ('description_en' = 'Catalogue definition of product from perspective of controlling. Controlling uses unified catalogue for whole company');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_life_policy_case SET TAGS ('description_en' = 'Defined (one particular) policy related business process or activity that is organization/domain has reason to monitor and/or record. It is sale process, either selling a new policy or making a change on it');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_life_policy_event SET TAGS ('description_en' = 'Event that occurs on life policy. It can be important activity, like creation of policy or technical change, but also a small change, like change of party\'s address');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_technical_id SET TAGS ('description_en' = 'Id that has no business meaning');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_agents SET TAGS ('description_en' = 'Sales relationship from organizational perspective with assigned "ziskatelske cislo". Defined as agent, where user belonging to GCZPerson of this agent\'s has domain other than "cpas". ("servis") An identity created for a person in a computer or computing system');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_application SET TAGS ('description_en' = 'System/application (definition, not particular instance). E.g., TIA, HUGO, LISA2');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_company SET TAGS ('description_en' = 'Juridical person (legal entity) that belongs to GCZ group, e.g., GCP, GCD. Company that is closely connected to GCZ');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_data_updated_at SET TAGS ('description_en' = 'Technical attribute that represents date and time from which PolicyOrInsurance data were updated from CORE system. Technical attribute that represents date and time from which PolicyOrInsurance data were updated from CORE system. This is metadata, this has no business meaning');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_number SET TAGS ('description_en' = 'Unique and public identifier');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_party_in_policy SET TAGS ('description_en' = 'Party is real world person or its suborganization that can be interpreted as client or client related. Typically, it is person or its suborganization that has at least one role on policy as policyholder or insured or at least one role on claim as claimant. Information about party in one particular context. Context re predefined (policy, claim, client zone,...). Context is object from different domain. That means that information about party in context is owned by different domain and this is only copy of it. E.g. party in policy or party in claim. Information about party that is valid only in context of particular insurance or policy');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_payment_frequency SET TAGS ('description_en' = 'Frequency of premium payments, e.g., monthly, yearly');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_period_final_discounted SET TAGS ('description_en' = 'Amount of money paid as policy premium in a chosen period after discount');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_status SET TAGS ('description_en' = 'Insurance\'s or insurance contract\'s status, e.g., active, terminated');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_super SET TAGS ('description_en' = 'Flag that represents whether this is instance of SuperPolicyOrInsurance. Legacy also called "ramcovka"');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_super_policy_reference SET TAGS ('description_en' = 'Overview information about insurance or insurance contract of partner with GCZ group company. Overview information about insurance frame (or quasi-frame like fleet) contract of partner with GCZ group company');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_valid_from SET TAGS ('description_en' = 'Date from which product instance is valid');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_valid_to SET TAGS ('description_en' = 'Date until which product instance is valid');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN life_policy_yearly_premium SET TAGS ('description_en' = 'Amount of money that partner is obliged to pay for one year of insurance');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __message_valid_flag SET TAGS ('description_en' = 'TRUE when the message matched the declared column structure. Because the structural columns are typed, Databricks turns a type mismatch into NULL instead of failing, so this flag and __rescued_data are the only way a mismatch becomes visible. The row is still landed; nothing is rejected in bronze.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __message_error_desc SET TAGS ('description_en' = 'What exactly does not match, where __message_valid_flag is FALSE. Holds the field path and the reason, for example an unexpected field, a missing mandatory field or a value that does not satisfy the declared pattern.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __rescued_data SET TAGS ('description_en' = 'Fields that did not fit the declared column structure, with their values, serialised as JSON. With typed structural columns this is the only place a new or retyped field survives; without it the value would be silently dropped or nulled.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __schema_version_id SET TAGS ('description_en' = 'Identifier of the schema from the schema registry that the message was written with. Read from the message envelope, so it is known even for a message that fails validation.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __trace_id SET TAGS ('description_en' = 'Unique identifier of the transaction. Identifies one particular transaction.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __msg_id SET TAGS ('description_en' = 'Unique identifier of the message. Identifies one particular call.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __source_eap_id SET TAGS ('description_en' = 'Identifier of the source system taken from the EAP application (eapId).');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __user_domain_login SET TAGS ('description_en' = 'User name including the domain.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __kafka_partition SET TAGS ('description_en' = 'Identifier of the Kafka partition the message was read from. It identifies the origin of the message within the topic and, together with the offset, determines its exact order within that partition.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __kafka_offset SET TAGS ('description_en' = 'Unique position of the message within a Kafka partition. The offset is an increasing number assigned by the Kafka broker when the message is stored and is used for processing tracking, deduplication and read recovery.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __kafka_timestamp SET TAGS ('description_en' = 'Kafka timestamp of when the message arrived.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __source_system SET TAGS ('description_en' = 'Source system.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __load_timestamp SET TAGS ('description_en' = 'Timestamp of when the record was added to the table.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __file_name SET TAGS ('description_en' = 'Name of the source file.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN __file_path SET TAGS ('description_en' = 'Path of the source file.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_lisa.life_policy_sales_cockpit_sync_event ALTER COLUMN case_number SET TAGS ('data_classification' = 'confidential');

-- ========================= dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event =========================
-- source     : NonlifePolicyOverviewSyncEvent_v1.avsc
-- key schema : PolicyOverview_Key.avsc
-- system     : TIA   load: Kafka sync   grain: One row per Kafka message
CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event (
    application_id                                   INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Identifikátor zdrojové aplikace. Součást klíče Kafka zprávy a způsob, jak se rozliší TIA od KDP.',
    policy_number                                    BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         NOT NULL  COMMENT 'Unikátní a veřejný identifikátor pojistné smlouvy. Součást klíče Kafka zprávy.',
    audit_information_application                    STRUCT<`id`: INT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              NOT NULL  COMMENT 'Systém nebo aplikace jako definice, nikoliv konkrétní instance. Například TIA, HUGO nebo LISA2.',
    audit_information_last_updated_at                TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      NOT NULL  COMMENT 'Datum a čas poslední aktualizace objektu nebo atributu.',
    audit_information_user                           STRUCT<`domain_login`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 NOT NULL  COMMENT 'Uzivatel systemu nebo aplikace',
    nonlife_policy_catalogue_nonlife_product_bundle  STRUCT<`code`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         NOT NULL  COMMENT 'Katalogová definice balíčku produktů z pohledu controllingu. Controlling používá jednotný katalog pro celou společnost.',
    nonlife_policy_nonlife_product_instances         ARRAY<STRUCT<`agreement_line`: STRUCT<`number`: BIGINT>, `catalogue_product`: STRUCT<`code`: INT>, `property_locations`: ARRAY<STRUCT<`address_point`: STRUCT<`country`: STRING, `evidence_number`: STRING, `land_register_number`: STRING, `municipality`: STRING, `municipality_part`: STRING, `ruian_address_point`: STRUCT<`code`: BIGINT>, `street`: STRING, `street_number`: STRING, `zip_code`: STRING>, `cadastral_plot`: STRUCT<`cadastral_area`: STRUCT<`id`: BIGINT, `name`: STRING>, `number`: STRING, `sub_number`: STRING>>>, `signed_on`: DATE, `status`: INT, `valid_from`: DATE, `valid_to`: DATE, `vehicles`: ARRAY<STRUCT<`brand`: STRING, `category`: STRING, `engine`: STRUCT<`displacement`: INT, `power`: INT>, `identification_number`: STRING, `manufactured`: INT, `registration_number`: STRING, `type`: STRING>>, `yearly_premium`: DECIMAL(38,2)>>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                NOT NULL  COMMENT 'Prehledove informace ohledne nezivotniho produktu pojisteni (jeho instance) partnera s GCZ skupinou.',
    nonlife_policy_admins                            ARRAY<STRUCT<`domain_login`: STRING, `registered_agent`: STRUCT<`id`: INT, `order`: INT, `share`: DECIMAL(38,2)>, `role`: INT>>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COMMENT 'Digitalni kancelar obchodniho zastupce. Primy nebo tranzitivni obchodni vztah nebo jeho podvztah jakekoliv spolecnosti GCZ s obchodnim subjektem, tedy podminky, za kterych osoba provadi prodej pro spolecnost skupiny GCZ. Jedinecne evidencni cislo databaze v SAP. Uzivatel systemu nebo aplikace',
    nonlife_policy_application                       STRUCT<`id`: INT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              NOT NULL  COMMENT 'Systém nebo aplikace jako definice, nikoliv konkrétní instance. Například TIA, HUGO nebo LISA2.',
    nonlife_policy_cancelled_on                      DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum zruseni pojisteni nebo pojistovaci smlouvy.',
    nonlife_policy_company                           STRUCT<`id`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           NOT NULL  COMMENT 'Pravnicka osoba (pravnicka osoba), ktera patri do skupiny GCZ, napr. GCP, GCD.',
    nonlife_policy_data_updated_at                   TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      NOT NULL  COMMENT 'Technický atribut s datem a časem, od kterého byla data smlouvy aktualizována z core systému.',
    nonlife_policy_legacy_generali                   STRUCT<`cancellation_reason`: STRING, `quotation_number`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               COMMENT 'Interni struktura, ktera reprezentuje relevantni data pro stare Generali smlouvy.',
    nonlife_policy_number                            BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         NOT NULL  COMMENT 'Unikatni a verejny identifikator (Cislo smlouvy).',
    nonlife_policy_original_valid_to                 DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum konce platnosti pojištění nebo pojistné smlouvy, jak bylo sjednáno v okamžiku podpisu.',
    nonlife_policy_parties_in_policy                 ARRAY<STRUCT<`addresses`: STRUCT<`correspondence`: STRUCT<`additional_delivery_instruction`: STRING, `audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `country`: STRING, `evidence_number`: STRING, `ext_id`: BIGINT, `land_register_number`: STRING, `municipality`: STRING, `municipality_part`: STRING, `ruian_address_point`: STRUCT<`code`: BIGINT>, `street`: STRING, `street_number`: STRING, `zip_code`: STRING>>, `electronic_contacts`: STRUCT<`email`: STRUCT<`audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `email_address`: STRING, `ext_id`: BIGINT>, `fixed_line`: STRUCT<`audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `ext_id`: BIGINT, `phone_number_format_choice`: STRUCT<`international`: STRUCT<`full_number`: STRING>, `structured`: STRUCT<`international_prefix`: INT, `national_number`: STRING>>>, `mobile_phone`: STRUCT<`audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `ext_id`: BIGINT, `phone_number_format_choice`: STRUCT<`international`: STRUCT<`full_number`: STRING>, `structured`: STRUCT<`international_prefix`: INT, `national_number`: STRING>>>>, `party`: STRUCT<`party_id`: STRING>, `roles`: ARRAY<STRUCT<`party_system_record`: STRUCT<`ext_id`: BIGINT>, `type`: INT>>>> NOT NULL  COMMENT 'Informace o partnerovi, jeho osobni a byznys informace. Informace o parnerovi ve specifikem kontextu, ktery je z jine domeny. Informace o partnerovy, ktere jsou platne jen v kontextu urcite smlouvy nebo pojisteni.',
    nonlife_policy_payment_activation_deadline       DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, do kterého musí být připsána první platba pojistného, jinak smlouva nenabude platnosti.',
    nonlife_policy_payment_frequency                 INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Frekvence s jakou se musi platit pojistne (mesicni, rocni). Codelist: KCC.ZpusPlac.',
    nonlife_policy_renewal_on                        DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum kdy pojisteni nebo pojistna smlouva je automaticky obnovena.',
    nonlife_policy_signed_on                         DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum kdy bylo pojisteni nebo pojistovaci smlouva byla podepsana.',
    nonlife_policy_status                            INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Stav pojiseni nebo smlouvy. Codelist: KCC.StavPojSml.',
    nonlife_policy_super                             BOOLEAN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        NOT NULL  COMMENT 'Příznak, zda jde o rámcovou smlouvu. Ve starém systému nazývaná ramcovka.',
    nonlife_policy_super_policy_reference            STRUCT<`number`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Vybrane informace o pojisteni nebo pojistovaci smlouve partnera s GCZ skupinou. Prehledne informace o pojistne ramcove (nebo kvazi-ramcove flotilove) smlouve partnera se spolecnosti skupiny GCZ.',
    nonlife_policy_valid_from                        DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, od kterého je instance produktu platná.',
    nonlife_policy_valid_to                          DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, do kterého je instance produktu platná.',
    nonlife_policy_version_valid_from                DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, od kterého je aktuální verze platná.',
    nonlife_policy_yearly_premium                    DECIMAL(38,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  NOT NULL  COMMENT 'Mnozstvi penez, ktere musi partner platit za jeden rok pojisteni.',
    __message_valid_flag                             BOOLEAN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        NOT NULL  COMMENT 'TRUE, když zpráva odpovídala deklarované struktuře sloupců. Protože jsou strukturní sloupce typované, Databricks při neshodě typu nespadne, ale uloží NULL, takže tento příznak a __rescued_data jsou jediný způsob, jak se neshoda projeví. Řádek se i tak uloží, v bronze se nic neodmítá.',
    __message_error_desc                             STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Co konkrétně nesedí, pokud je __message_valid_flag FALSE. Obsahuje cestu k položce a důvod, například neočekávané pole, chybějící povinné pole nebo hodnotu nesplňující deklarovaný pattern.',
    __rescued_data                                   STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Pole, která se do deklarované struktury sloupců nevešla, včetně hodnot, serializovaná jako JSON. U typovaných strukturních sloupců je to jediné místo, kde nové nebo přetypované pole přežije; bez něj by se hodnota tiše ztratila nebo znulovala.',
    __schema_version_id                              INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             COMMENT 'Identifikátor schématu z schema registry, kterým byla zpráva zapsána. Čte se z obálky zprávy, takže je znám i u zprávy, která neprojde validací.',
    __trace_id                                       STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Unikátní identifikátor transakce. Jedná se o identifikátor konkrétní transakce.',
    __msg_id                                         STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Unikátní identifikátor zprávy. Jedná se o identifikátor konkrétního volání.',
    __source_eap_id                                  STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Identifikátor zdrojového systému z aplikace EAP (eapId)',
    __user_domain_login                              STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Uživatelské jméno (s doménou)',
    __kafka_partition                                INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             COMMENT 'Identifikátor Kafka partition, ze které byla zpráva načtena. Slouží k jednoznačné identifikaci původu zprávy v rámci topicu a společně s offsetem umožňuje určit její přesné pořadí v dané partition.',
    __kafka_offset                                   BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Jedinečná pozice zprávy v rámci Kafka partition. Offset je průběžně rostoucí číslo přidělené brokerem Kafka při uložení zprávy a používá se pro sledování zpracování, deduplikaci a obnovu čtení dat.',
    __kafka_timestamp                                TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       COMMENT 'Kafka - časové razítko, kdy zpráva přišla.',
    __source_system                                  STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Zdrojový systém',
    __load_timestamp                                 TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name                                      STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Jméno zdrojového souboru',
    __file_path                                      STRING                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          COMMENT 'Cesta ke zdrojovému souboru',
    CONSTRAINT pk_nonlife_policy_overview_sync_event PRIMARY KEY (application_id, policy_number) NOT ENFORCED
)
USING DELTA
COMMENT 'Aktuální snapshot neživotní smlouvy nebo stavu před uzavřením ze systému TIA. Zpráva neobsahuje informaci, zda jde o vytvoření, aktualizaci nebo vymazání, ani identifikátor z HUGO. Jako datum vzniku smlouvy se bere signedOn, ten se ale mění při novém podpisu a vyplňuje se i předpokládaným datem, což musí řešit logika zpracování.'
CLUSTER BY (application_id, policy_number)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'TIA',
    'source.object'              = 'NonlifePolicyOverviewSyncEvent_v1.avsc',
