ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event ALTER COLUMN nonlife_policy_application SET TAGS ('description_en' = 'System/application (definition, not particular instance). E.g., TIA, HUGO, LISA2');
