ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event ALTER COLUMN nonlife_policy_parties_in_policy SET TAGS ('description_en' = 'Party is real world person or its suborganization that can be interpreted as client or client related. Typically, it is person or its suborganization that has at least one role on policy as policyholder or insured or at least one role on claim as claimant. Information about party in one particular context. Context re predefined (policy, claim, client zone,...). Context is object from different domain. That means that information about party in context is owned by different domain and this is only copy of it. E.g. party in policy or party in claim. Information about party that is valid only in context of particular insurance or policy');
