ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event ALTER COLUMN __message_valid_flag SET TAGS ('description_en' = 'TRUE when the message matched the declared column structure. Because the structural columns are typed, Databricks turns a type mismatch into NULL instead of failing, so this flag and __rescued_data are the only way a mismatch becomes visible. The row is still landed; nothing is rejected in bronze.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event ALTER COLUMN __message_error_desc SET TAGS ('description_en' = 'What exactly does not match, where __message_valid_flag is FALSE. Holds the field path and the reason, for example an unexpected field, a missing mandatory field or a value that does not satisfy the declared pattern.');
