ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event ALTER COLUMN __schema_version_id SET TAGS ('description_en' = 'Identifier of the schema from the schema registry that the message was written with. Read from the message envelope, so it is known even for a message that fails validation.');
