ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event ALTER COLUMN __kafka_partition SET TAGS ('description_en' = 'Identifier of the Kafka partition the message was read from. It identifies the origin of the message within the topic and, together with the offset, determines its exact order within that partition.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_tia.nonlife_policy_overview_sync_event ALTER COLUMN __kafka_offset SET TAGS ('description_en' = 'Unique position of the message within a Kafka partition. The offset is an increasing number assigned by the Kafka broker when the message is stored and is used for processing tracking, deduplication and read recovery.');
