    application_id                           INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Identifikátor zdrojové aplikace. Součást klíče Kafka zprávy a způsob, jak se rozliší KDP od TIA.',
