    life_policy_application                  STRUCT<`id`: INT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              NOT NULL  COMMENT 'Systém nebo aplikace jako definice, nikoliv konkrétní instance. Například TIA, HUGO nebo LISA2.',
    life_policy_cancelled_on                 DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum zruseni pojisteni nebo pojistovaci smlouvy.',
    life_policy_company                      STRUCT<`id`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           NOT NULL  COMMENT 'Pravnicka osoba (pravnicka osoba), ktera patri do skupiny GCZ, napr. GCP, GCD.',
    life_policy_data_updated_at              TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      NOT NULL  COMMENT 'Technický atribut s datem a časem, od kterého byla data smlouvy aktualizována z core systému.',
    life_policy_legacy_generali              STRUCT<`cancellation_reason`: STRING, `quotation_number`: STRING>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               COMMENT 'Interni struktura, ktera reprezentuje relevantni data pro stare Generali smlouvy.',
    life_policy_number                       BIGINT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         NOT NULL  COMMENT 'Unikatni a verejny identifikator (Cislo smlouvy).',
    life_policy_original_valid_to            DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum konce platnosti pojištění nebo pojistné smlouvy, jak bylo sjednáno v okamžiku podpisu.',
    life_policy_parties_in_policy            ARRAY<STRUCT<`addresses`: STRUCT<`correspondence`: STRUCT<`additional_delivery_instruction`: STRING, `audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `country`: STRING, `evidence_number`: STRING, `ext_id`: BIGINT, `land_register_number`: STRING, `municipality`: STRING, `municipality_part`: STRING, `ruian_address_point`: STRUCT<`code`: BIGINT>, `street`: STRING, `street_number`: STRING, `zip_code`: STRING>>, `electronic_contacts`: STRUCT<`email`: STRUCT<`audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `email_address`: STRING, `ext_id`: BIGINT>, `fixed_line`: STRUCT<`audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `ext_id`: BIGINT, `phone_number_format_choice`: STRUCT<`international`: STRUCT<`full_number`: STRING>, `structured`: STRUCT<`international_prefix`: INT, `national_number`: STRING>>>, `mobile_phone`: STRUCT<`audit_information`: STRUCT<`application`: STRUCT<`id`: INT>, `last_updated_at`: TIMESTAMP, `user`: STRUCT<`domain_login`: STRING>>, `ext_id`: BIGINT, `phone_number_format_choice`: STRUCT<`international`: STRUCT<`full_number`: STRING>, `structured`: STRUCT<`international_prefix`: INT, `national_number`: STRING>>>>, `party`: STRUCT<`party_id`: STRING>, `roles`: ARRAY<STRUCT<`party_system_record`: STRUCT<`ext_id`: BIGINT>, `type`: INT>>>> NOT NULL  COMMENT 'Informace o partnerovi, jeho osobni a byznys informace. Informace o parnerovi ve specifikem kontextu, ktery je z jine domeny. Informace o partnerovy, ktere jsou platne jen v kontextu urcite smlouvy nebo pojisteni.',
    life_policy_payment_activation_deadline  DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, do kterého musí být připsána první platba pojistného, jinak smlouva nenabude platnosti.',
    life_policy_payment_frequency            INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Frekvence s jakou se musi platit pojistne (mesicni, rocni). Codelist: KCC.ZpusPlac.',
    life_policy_renewal_on                   DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum kdy pojisteni nebo pojistna smlouva je automaticky obnovena.',
    life_policy_signed_on                    DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum kdy bylo pojisteni nebo pojistovaci smlouva byla podepsana.',
    life_policy_status                       INT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NOT NULL  COMMENT 'Stav pojiseni nebo smlouvy. Codelist: KCC.StavPojSml.',
    life_policy_super                        BOOLEAN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        NOT NULL  COMMENT 'Příznak, zda jde o rámcovou smlouvu. Ve starém systému nazývaná ramcovka.',
    life_policy_super_policy_reference       STRUCT<`number`: BIGINT>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        COMMENT 'Vybrane informace o pojisteni nebo pojistovaci smlouve partnera s GCZ skupinou. Prehledne informace o pojistne ramcove (nebo kvazi-ramcove flotilove) smlouve partnera se spolecnosti skupiny GCZ.',
    life_policy_valid_from                   DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, od kterého je instance produktu platná.',
    life_policy_valid_to                     DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, do kterého je instance produktu platná.',
    life_policy_version_valid_from           DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            COMMENT 'Datum, od kterého je aktuální verze platná.',
    life_policy_yearly_premium               DECIMAL(38,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  NOT NULL  COMMENT 'Mnozstvi penez, ktere musi partner platit za jeden rok pojisteni.',
