CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_ccd.party_id_change_event (
    party_id                           STRING                         NOT NULL  COMMENT 'Unikátní identifikátor partnera. Klíč Kafka zprávy.',
    audit_information_application      STRUCT<`id`: INT>              NOT NULL  COMMENT 'Systém nebo aplikace jako definice, nikoliv konkrétní instance. Například TIA, HUGO nebo LISA2.',
    audit_information_last_updated_at  TIMESTAMP                      NOT NULL  COMMENT 'Datum a čas poslední aktualizace objektu nebo atributu.',
    audit_information_user             STRUCT<`domain_login`: STRING> NOT NULL  COMMENT 'Uzivatel systemu nebo aplikace',
    party_new_party_id                 STRING                         NOT NULL  COMMENT 'Unikatni identifikator partnera. Unique identifier. .',
    party_party_id                     STRING                         NOT NULL  COMMENT 'Unikatni identifikator partnera. Unique identifier. .',
    __message_valid_flag               BOOLEAN                        NOT NULL  COMMENT 'TRUE, když zpráva odpovídala deklarované struktuře sloupců. Protože jsou strukturní sloupce typované, Databricks při neshodě typu nespadne, ale uloží NULL, takže tento příznak a __rescued_data jsou jediný způsob, jak se neshoda projeví. Řádek se i tak uloží, v bronze se nic neodmítá.',
    __message_error_desc               STRING                          COMMENT 'Co konkrétně nesedí, pokud je __message_valid_flag FALSE. Obsahuje cestu k položce a důvod, například neočekávané pole, chybějící povinné pole nebo hodnotu nesplňující deklarovaný pattern.',
    __rescued_data                     STRING                          COMMENT 'Pole, která se do deklarované struktury sloupců nevešla, včetně hodnot, serializovaná jako JSON. U typovaných strukturních sloupců je to jediné místo, kde nové nebo přetypované pole přežije; bez něj by se hodnota tiše ztratila nebo znulovala.',
    __schema_version_id                INT                             COMMENT 'Identifikátor schématu z schema registry, kterým byla zpráva zapsána. Čte se z obálky zprávy, takže je znám i u zprávy, která neprojde validací.',
    __trace_id                         STRING                          COMMENT 'Unikátní identifikátor transakce. Jedná se o identifikátor konkrétní transakce.',
    __msg_id                           STRING                          COMMENT 'Unikátní identifikátor zprávy. Jedná se o identifikátor konkrétního volání.',
    __source_eap_id                    STRING                          COMMENT 'Identifikátor zdrojového systému z aplikace EAP (eapId)',
    __user_domain_login                STRING                          COMMENT 'Uživatelské jméno (s doménou)',
    __kafka_partition                  INT                             COMMENT 'Identifikátor Kafka partition, ze které byla zpráva načtena. Slouží k jednoznačné identifikaci původu zprávy v rámci topicu a společně s offsetem umožňuje určit její přesné pořadí v dané partition.',
    __kafka_offset                     BIGINT                          COMMENT 'Jedinečná pozice zprávy v rámci Kafka partition. Offset je průběžně rostoucí číslo přidělené brokerem Kafka při uložení zprávy a používá se pro sledování zpracování, deduplikaci a obnovu čtení dat.',
    __kafka_timestamp                  TIMESTAMP                       COMMENT 'Kafka - časové razítko, kdy zpráva přišla.',
    __source_system                    STRING                          COMMENT 'Zdrojový systém',
    __load_timestamp                   TIMESTAMP                       COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name                        STRING                          COMMENT 'Jméno zdrojového souboru',
    __file_path                        STRING                          COMMENT 'Cesta ke zdrojovému souboru',
    CONSTRAINT pk_party_id_change_event PRIMARY KEY (party_id) NOT ENFORCED
)
USING DELTA
COMMENT 'Změna identifikátoru klienta ze systému CCD, typicky sloučení duplicitních záznamů. Zpráva nese původní partyId a nové partyId.'
CLUSTER BY (party_id)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'CCD',
    'source.object'              = 'PartyIdChangeEvent_v1.avsc',
    'load.pattern'               = 'Kafka sync'
);
