-- ========================= dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine =========================
-- source     : NonlifePolicySalesCockpitSyncEvent_v1_1.avsc
-- system     : HUGO   load: Kafka dead letter   grain: One row per message that could not be deserialised
CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine (
    quarantine_id        BIGINT    GENERATED ALWAYS AS IDENTITY NOT NULL  COMMENT 'Náhradní identifikátor zprávy v karanténě.',
    kafka_topic          STRING    NOT NULL  COMMENT 'Kafka topic, ze kterého byla zpráva načtena.',
    source_object        STRING     COMMENT 'AVRO value schéma, které konzument pro tento topic očekával.',
    raw_key              BINARY     COMMENT 'Surové bajty klíče zprávy přesně tak, jak byly přijaty. Uchovávají se, protože zprávu, kterou nelze dekódovat, nelze uložit jako VARIANT.',
    raw_value            BINARY     COMMENT 'Surové bajty těla zprávy přesně tak, jak byly přijaty. Právě díky nim je možný replay, jakmile se příčina odstraní.',
    error_type_code      STRING    NOT NULL  COMMENT 'Proč zprávu nešlo dekódovat: DESERIALIZATION_FAILED, SCHEMA_NOT_FOUND, SCHEMA_INCOMPATIBLE nebo ENVELOPE_INVALID.',
    error_desc           STRING     COMMENT 'Text chyby deserializace tak, jak ji ohlásil čtecí proces.',
    schema_version_id    INT        COMMENT 'Identifikátor schématu z registry přečtený z obálky zprávy, pokud je samotná obálka čitelná.',
    retry_count          INT       NOT NULL  COMMENT 'Kolikrát byl pokus o replay této zprávy proveden.',
    resolved_flag        BOOLEAN   NOT NULL  COMMENT 'TRUE, jakmile byla zpráva úspěšně přehrána do své bronze tabulky. Řádek zde zůstává jako auditní stopa.',
    __trace_id           STRING     COMMENT 'Unikátní identifikátor transakce. Jedná se o identifikátor konkrétní transakce.',
    __msg_id             STRING     COMMENT 'Unikátní identifikátor zprávy. Jedná se o identifikátor konkrétního volání.',
    __source_eap_id      STRING     COMMENT 'Identifikátor zdrojového systému z aplikace EAP (eapId)',
    __user_domain_login  STRING     COMMENT 'Uživatelské jméno (s doménou)',
    __kafka_partition    INT        COMMENT 'Identifikátor Kafka partition, ze které byla zpráva načtena. Slouží k jednoznačné identifikaci původu zprávy v rámci topicu a společně s offsetem umožňuje určit její přesné pořadí v dané partition.',
    __kafka_offset       BIGINT     COMMENT 'Jedinečná pozice zprávy v rámci Kafka partition. Offset je průběžně rostoucí číslo přidělené brokerem Kafka při uložení zprávy a používá se pro sledování zpracování, deduplikaci a obnovu čtení dat.',
    __kafka_timestamp    TIMESTAMP  COMMENT 'Kafka - časové razítko, kdy zpráva přišla.',
    __source_system      STRING     COMMENT 'Zdrojový systém',
    __load_timestamp     TIMESTAMP  COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name          STRING     COMMENT 'Jméno zdrojového souboru',
    __file_path          STRING     COMMENT 'Cesta ke zdrojovému souboru',
    CONSTRAINT pk_kafka_message_quarantine PRIMARY KEY (quarantine_id) NOT ENFORCED
)
USING DELTA
COMMENT 'Karanténní tabulka pro zprávy tohoto zdroje, které se vůbec nepodařilo deserializovat, a nemohly tak být uloženy do své bronze tabulky. Uchovávají se surové bajty, což je jediná podoba, která přežije neúspěšné dekódování a jediná, kterou lze použít pro replay. Nic se nikdy nezahazuje.'
CLUSTER BY (quarantine_id)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'HUGO',
    'source.object'              = 'NonlifePolicySalesCockpitSyncEvent_v1_1.avsc',
    'load.pattern'               = 'Kafka dead letter'
);
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine SET TAGS ('description_en' = 'Dead letter table for messages of this source that could not be deserialised at all, so they could not be landed in their bronze table. The raw bytes are kept, which is the only form that survives a failed decode and the only form a replay can use. Nothing is ever discarded.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN quarantine_id SET TAGS ('description_en' = 'Surrogate identifier of the quarantined message.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN kafka_topic SET TAGS ('description_en' = 'Kafka topic the message was consumed from.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN source_object SET TAGS ('description_en' = 'AVRO value schema the consumer expected for this topic.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN raw_key SET TAGS ('description_en' = 'Raw bytes of the message key, exactly as received. Kept because a message that cannot be decoded cannot be held as VARIANT.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN raw_value SET TAGS ('description_en' = 'Raw bytes of the message value, exactly as received. This is what makes a replay possible once the cause is fixed.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN error_type_code SET TAGS ('description_en' = 'Why the message could not be decoded: DESERIALIZATION_FAILED, SCHEMA_NOT_FOUND, SCHEMA_INCOMPATIBLE or ENVELOPE_INVALID.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN error_desc SET TAGS ('description_en' = 'Message of the deserialisation error, as reported by the reader.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN schema_version_id SET TAGS ('description_en' = 'Schema registry identifier read from the message envelope, where the envelope itself is readable.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN retry_count SET TAGS ('description_en' = 'How many times a replay of this message has been attempted.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN resolved_flag SET TAGS ('description_en' = 'TRUE once the message has been successfully replayed into its bronze table. The row stays here as an audit trail.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __trace_id SET TAGS ('description_en' = 'Unique identifier of the transaction. Identifies one particular transaction.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __msg_id SET TAGS ('description_en' = 'Unique identifier of the message. Identifies one particular call.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __source_eap_id SET TAGS ('description_en' = 'Identifier of the source system taken from the EAP application (eapId).');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __user_domain_login SET TAGS ('description_en' = 'User name including the domain.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __kafka_partition SET TAGS ('description_en' = 'Identifier of the Kafka partition the message was read from. It identifies the origin of the message within the topic and, together with the offset, determines its exact order within that partition.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __kafka_offset SET TAGS ('description_en' = 'Unique position of the message within a Kafka partition. The offset is an increasing number assigned by the Kafka broker when the message is stored and is used for processing tracking, deduplication and read recovery.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __kafka_timestamp SET TAGS ('description_en' = 'Kafka timestamp of when the message arrived.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __source_system SET TAGS ('description_en' = 'Source system.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.src_hugo.kafka_message_quarantine ALTER COLUMN __load_timestamp SET TAGS ('description_en' = 'Timestamp of when the record was added to the table.');
