    id_ruian              BIGINT         COMMENT 'Položka adresního materiálu - ID adresního bodu v RUIANU (pro párování brutto produkce)',
    party_id              STRING         COMMENT 'ID partnera',
    date_inserted         TIMESTAMP      COMMENT 'Technický datum pro zpracování - datum, kdy byl záznam vložen do této tabulky - může být datem, kdy došlo k vytvoření záznamu nebo aktualizaci záznamu na zdroji.',
    __source_system       STRING         COMMENT 'Zdrojový systém',
    __load_timestamp      TIMESTAMP      COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
