CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.kcl.bdt_campaign_wave (
    id                    BIGINT        NOT NULL  COMMENT 'ID kamapně',
    description           STRING         COMMENT 'Popis kampaně',
    end_date              TIMESTAMP     NOT NULL  COMMENT 'Datum konce kampaně (Počítá se včetně celého posledního dne do 23:59:59.)',
    expected_value        DECIMAL(10,2)  COMMENT 'Očekávaná produkce na kontakt (Jen pro standardní kampaně.)',
    start_date            TIMESTAMP     NOT NULL  COMMENT 'Začátek kampaně (Bere se jen datum bez času a k datu se nic nepřidává.)',
    valid_from            DATE           COMMENT 'Historický příznak počátku platnosti záznamu (Nyní platí záznam v sloupci DATE_CREATED.)',
    valid_to              DATE           COMMENT 'Přiznak vymazané kampaně (Když je null, tak stále aktivní, když je větší než aktuální datum pro staré záznamy, tak též aktivní.)',
    date_created          TIMESTAMP      COMMENT 'Datum a čas vzniku záznamu (Bere se jak je.)',
    date_modified         TIMESTAMP      COMMENT 'Datum a čas poslední modifikace záznamu (Bere se jak je.)',
    campaign_code         STRING        NOT NULL  COMMENT 'Kód kampaně',
    campaign_name         STRING        NOT NULL  COMMENT 'Název kampaně',
    channel_id            INT           NOT NULL  COMMENT 'ID kanálu kampaně',
    communication_code    STRING        NOT NULL  COMMENT 'Kód komunikace',
    communication_name    STRING        NOT NULL  COMMENT 'Název komunikace',
    campaign_type         BIGINT         COMMENT 'Typ kampaně (0 - Standardní, 3 - Dožití)',
    expected_replacement  BIGINT         COMMENT 'V procentech očekávaná náhrada životního pojištění na kampaň',
    production_plan       BIGINT         COMMENT 'Očekávaná celková produkce na kampaň (Jen pro kampaně 3 - Dožití. Produkce na kontakt se pak vypočívá podle počtu kontaktů v kampani.)',
    company_id            INT           NOT NULL  COMMENT 'ID společnosti (Rozlišení zda jde o novou nebo starou Generali pojišťovnu.)',
    microcampaign         INT           NOT NULL  COMMENT 'Příznak mikrokampaně',
    founder               STRING         COMMENT 'Login zakladatele mikrokampaně',
    __source_system       STRING         COMMENT 'Zdrojový systém',
    __load_timestamp      TIMESTAMP      COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    CONSTRAINT pk_bdt_campaign_wave PRIMARY KEY (id) NOT ENFORCED
)
USING DELTA
COMMENT 'Data o kampani'
CLUSTER BY (id)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'KCL',
    'source.object'              = 'KCL2.BDT_CAMPAIGN_WAVE',
    'load.pattern'               = 'ETL incremental'
);
