-- source     : KCC.Produkt
-- system     : KCC   load: Landing CSV, denně: ALL_H_Produkt.csv   grain: One row per source row
CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_kcc.produkt (
    tk                    INT           COMMENT 'Technologický klíč',
    id_akt                TIMESTAMP     COMMENT 'Datum provedení změny',
    plati_od              TIMESTAMP     COMMENT 'Počátek platnosti záznamu',
    plati_do              TIMESTAMP     COMMENT 'Konec platnosti záznamu',
    publik_od             TIMESTAMP     COMMENT 'Datum, od kdy je údaj publikován v číselníku',
    publik_do             TIMESTAMP     COMMENT 'Datum, do kdy je údaj publikován v číselníku',
    kod_produkt           INT          NOT NULL  COMMENT 'Kód produktu',
    kr_naz_produkt        STRING        COMMENT 'Krátký název produktu',
    dl_naz_produkt        STRING        COMMENT 'Dlouhý název produktu',
    text_sloz             STRING        COMMENT 'Text pro tisk na složenkách Význam hodnot: Nutno vyplnit u produktů, u nichž je předpoklad tisku složenek. Bez vyplnění je produkt pro tiskové úlohy "neviditelný".',
    kod_org_produkt       SMALLINT      COMMENT 'Kód organizace, která nastavuje parametry odměňování, zajišťuje propojení na matriku obchodníků, účtuje odpisy Význam hodnot: Získány z číselníku Organiz',
    fikt_produkt          STRING        COMMENT 'Fiktivní produkt (fiktivní úroveň ke skup. poj. pro analýzu ziskovosti) Význam hodnot: 0 (popř. Null) = NE (Produkt není fiktivní) 1 = ANO (produkt je fiktivní)',
    depo_zadr             STRING        COMMENT 'Druh provize - zadržována/deponována/ani zadržována,ani deponována Význam hodnot: 0 = Zadržováno 1 = Deponováno 2 = Ani-ani',
    sjednavan             STRING        COMMENT 'Stav produktu Význam hodnot: S = Sjednáván N = Nesjednáván null = nemá význam označení sjednáván ani nesjednáván',
    prod_plat_od          TIMESTAMP     COMMENT 'Datum počátku sjednávání produktu Význam hodnot: Datum',
    prod_plat_do          TIMESTAMP     COMMENT 'Datum ukončení sjednávání produktu Význam hodnot: Vyplnit souběžně s Sjednavan = N',
    vazba_psp             STRING        COMMENT 'Vazba do databáze PSP - Prodejně-servisní portál (HUGO)',
    zkrat                 STRING        COMMENT 'Zkratka',
    cizi                  SMALLINT      COMMENT 'Sjednávání podle cizích pojistných podmínek Význam hodnot: 1 = ANO',
    tum                   DECIMAL(3,1)  COMMENT 'Technická úroková míra',
    zpus_vykaz            INT           COMMENT 'Způsob vykazování Význam hodnot: 0 - standardní vykaz 1 - u ŽP vykazovat vždy právě jedno hl. riziko',
    kr_text_sloz          STRING        COMMENT 'Krátký text složenky - figuruje na složence v poli: Účel platby',
    obch_naz_produkt      STRING        COMMENT 'Obsahuje názvy produktů obsažené v obchodních směrnicích',
    dan_uznatelnost       STRING        COMMENT 'Daňově uznatelné Význam hodnot: Y - Ano N - Ne',
    seskupeni             INT           COMMENT 'Příslušnost každého produktu ke konkrétnímu seskupení. Význam hodnot: Vazba na ciselnik SeskupProdukt',
    kod_storno_alg        SMALLINT      COMMENT 'Kód storno algoritmu Význam hodnot: 0 - standardní storno algoritmus 1 - individuální storno algoritmus (automatický)',
    obch_naz_produkt_jok  STRING        COMMENT 'Název produktu pro JOK (př. aplikace Next Best Offer)',
    kateg_poji            SMALLINT      COMMENT 'Definice kategorie pojištění pro Zajištění Neživota Význam hodnot: Null = produkty ŽP 1 = Majetek 2 = Odpovědnost 3 = Auta-motorová vozidla',
    portfolio             STRING        COMMENT 'Definice portfolia pojištění pro Zajištění Neživota Význam hodnot: Null = produkty ŽP RES = (občanské pojištění) COM = (neobčanské pojištění) IND = (průmyslové pojištění)',
    typ_poj_obdobi        SMALLINT      COMMENT 'Typ poj. období pro výpočet pojistných období v Zajištění Neživota Význam hodnot: Null = produkty ŽP 1 = dle frekvence placení 2 = dle pojistné doby 3 = dle pojistné doby+záruční doby',
    typ_poji              STRING        COMMENT 'Typ pojištění pro naplnění atributů pro Zajištění Neživota Význam hodnot: SKOD=škodové OBNOS=obnosové',
    kod_zivot             STRING        COMMENT 'Výběr pro produkty spadající do kategorie - životní produkty Význam hodnot: 2 = životní produkty Null = ostatní',
    bp_jp_vklad           STRING        COMMENT 'Rozlišení způsobu placení dle produktu. Nezaměňovat se způsobem placení pro číselník Riziko Význam hodnot: BP=život_produkt běžně placený JP=život_produkt jednorázově placený JP_vklad=život_produkt jednorázově placený_návratný vklad',
    tr_ul                 STRING        COMMENT 'Rozlišení na produkty investiční a tradiční, dáno podstatou produktu a jak jsou vykazovány na ČNB. Výjimka pro 2 produkty Patriot, nanahlížíme na ně jako na investiční Význam hodnot: UL=produkt investiční (unit linked) TR=produkt ostatní tradiční (tradicional)',
    odkup                 STRING        COMMENT 'Životní pojištění - produkty, u kterých má klient po stornu právo na odkupné(odbytné) Význam hodnot: Y/Ano=rezervotvorné (vytváří se odbytné) N/Ne=nerezervotvorné(nevytváří se odbytné) Ostatní prázdné',
    sap_objid             STRING        COMMENT 'Číslo kvalifikace Produktového oprávnění (ze SAP)',
    nep_predpis           STRING        COMMENT 'Možnost sjednávání nepravidelného předpisu Význam hodnot: 1 = ano - Produkt umožňuje nepravidelný předpis splátek pro klienta 0 (popř. NULL) = NE - produkt neumožňuje nepravidelný předpis splátek pro klienta Plánováno užití pro produkty velkých riz',
    company_id            SMALLINT     NOT NULL  COMMENT 'ID společnosti Význam hodnot: Vazba na číselník Organiz.KodOrg',
    __source_system       STRING        COMMENT 'Zdrojový systém',
    __load_timestamp      TIMESTAMP     COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name           STRING        COMMENT 'Název souboru v landing zóně, ze kterého byl řádek načten.',
    __file_path           STRING        COMMENT 'Plná cesta k souboru v landing zóně, ze kterého byl řádek načten.',
    CONSTRAINT pk_produkt PRIMARY KEY (kod_produkt, company_id) NOT ENFORCED
)
USING DELTA
COMMENT 'Číselník produktů z pohledu controllingu a odměňování.'
CLUSTER BY (kod_produkt, company_id)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'KCC',
    'source.object'              = 'KCC.Produkt',
    'load.pattern'               = 'Landing CSV, denně: ALL_H_Produkt.csv'
);
