CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_kcc.dial_international_codes (
    tk                 INT        COMMENT 'Technologický klíč',
    id_akt             TIMESTAMP  COMMENT 'Datum provedení změny',
    plati_od           TIMESTAMP  COMMENT 'Počátek platnosti záznamu',
    plati_do           TIMESTAMP  COMMENT 'Konec platnosti záznamu',
    publik_od          TIMESTAMP  COMMENT 'Datum, od kdy je údaj publikován v číselníku',
    publik_do          TIMESTAMP  COMMENT 'Datum, do kdy je údaj publikován v číselníku',
    dial_code          INT        COMMENT 'Mezinárodní směrové číslo jednoznačně identifikuje národní telefonní síť, do které se má telefonovat. Nejprve se musí vytočit tzv. mezinárodní přestupný znak, který označuje, že hovor bude mezinárodní',
    country_code_iso2  STRING    NOT NULL  COMMENT 'Dvoumístný kód země podle ISO 3166 standard – Codes for the representation of names of countries and their subdivisions',
    country_code_iso3  STRING     COMMENT 'Třímístný kód země podle ISO 3166 standard – Codes for the representation of names of countries and their subdivisions',
    country_region     STRING     COMMENT 'Název země, případně oblasti pokryté daným kódem.',
    sequence           INT        COMMENT 'Uživatelsky definované pořadí pro zobrazování v aplikacích GČP',
    __source_system    STRING     COMMENT 'Zdrojový systém',
    __load_timestamp   TIMESTAMP  COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name        STRING     COMMENT 'Název souboru v landing zóně, ze kterého byl řádek načten.',
    __file_path        STRING     COMMENT 'Plná cesta k souboru v landing zóně, ze kterého byl řádek načten.',
    CONSTRAINT pk_dial_international_codes PRIMARY KEY (country_code_iso2) NOT ENFORCED
)
USING DELTA
COMMENT 'Číselník mezinárodních směrových čísel a ISO kódů zemí.'
CLUSTER BY (country_code_iso2)
