-- ========================= dbx_cz_gcz_dev_czlake_bronze.src_kcc.stav_poj_sml =========================
-- source     : KCC.StavPojSml
-- system     : KCC   load: Landing CSV, denně: ALL_H_StavPojSml.csv   grain: One row per source row
CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.src_kcc.stav_poj_sml (
    tk                INT        COMMENT 'Technologický klíč',
    id_akt            TIMESTAMP  COMMENT 'Datum provedení změny',
    plati_od          TIMESTAMP  COMMENT 'Počátek platnosti záznamu',
    plati_do          TIMESTAMP  COMMENT 'Konec platnosti záznamu',
    publik_od         TIMESTAMP  COMMENT 'Datum, od kdy je údaj publikován v číselníku',
    publik_do         TIMESTAMP  COMMENT 'Datum, do kdy je údaj publikován v číselníku',
    kod_stav          SMALLINT  NOT NULL  COMMENT 'kód stavu pojistné smlouvy',
    nazev_stav        STRING     COMMENT 'název stavu pojistné smlouvy',
    alfanum_kod       STRING     COMMENT 'alfanumerický kód stavu pojistné smlouvy',
    poradi            SMALLINT   COMMENT 'Pořadí prvků pro front-end',
    vyskyt_stavu      STRING     COMMENT 'Určuje, zda daný stav odpovídá SMLOUVĚ nebo NABÍDCE. Význam hodnot: N - nabídka, S - smlouva',
    company_id        SMALLINT  NOT NULL  COMMENT 'ID společností podle sloupce KCČ.Organiz.KodOrg Význam hodnot: Vazba na číselník Organiz.KodOrg',
    __source_system   STRING     COMMENT 'Zdrojový systém',
    __load_timestamp  TIMESTAMP  COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name       STRING     COMMENT 'Název souboru v landing zóně, ze kterého byl řádek načten.',
    __file_path       STRING     COMMENT 'Plná cesta k souboru v landing zóně, ze kterého byl řádek načten.',
    CONSTRAINT pk_stav_poj_sml PRIMARY KEY (kod_stav, company_id) NOT ENFORCED
)
USING DELTA
COMMENT 'Číselník stavů pojistné smlouvy a návrhu. Zdrojová hodnota VyskytStavu rozlišuje smlouvu od návrhu, ve zdroji pojmenovaného nabídka.'
CLUSTER BY (kod_stav, company_id)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'KCC',
    'source.object'              = 'KCC.StavPojSml',
    'load.pattern'               = 'Landing CSV, denně: ALL_H_StavPojSml.csv'
);
