-- ========================= dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit =========================
-- source     : StavPojSmlSalesCockpit
-- system     : Plao   load: Landing CSV, denně: StavPojSmlSalesCockpit_YYYYMMDD.csv   grain: One row per source row
CREATE TABLE IF NOT EXISTS dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit (
    company_id                SMALLINT  NOT NULL  COMMENT 'ID společnosti.',
    kod_stav                  SMALLINT  NOT NULL  COMMENT 'Kód stavu pojistné smlouvy.',
    nazev_stav_sales_cockpit  STRING     COMMENT 'Název stavu pojistné smlouvy používaný v Sales Cockpitu.',
    plati_od                  DATE      NOT NULL  COMMENT 'Datum, od kterého je mapování platné. Součást primárního klíče, protože tabulka nese historická data.',
    plati_do                  DATE       COMMENT 'Datum, do kterého je mapování platné. Prázdné u aktuálně platného záznamu.',
    __source_system           STRING     COMMENT 'Zdrojový systém',
    __load_timestamp          TIMESTAMP  COMMENT 'Časové razítko, kdy záznam byl přidán do tabulky.',
    __file_name               STRING     COMMENT 'Název souboru v landing zóně, ze kterého byl řádek načten.',
    __file_path               STRING     COMMENT 'Plná cesta k souboru v landing zóně, ze kterého byl řádek načten.',
    CONSTRAINT pk_stav_poj_sml_sales_cockpit PRIMARY KEY (company_id, kod_stav, plati_od) NOT ENFORCED
)
USING DELTA
COMMENT 'Mapovací tabulka stavů pojistné smlouvy na názvy stavů používané v Sales Cockpitu. Nahrává se ručně do landing zóny jako soubor StavPojSmlSalesCockpit_YYYYMMDD.csv. Napojuje se na číselník KCČ StavPojSml přes shodu KodStav a CompanyID a zároveň přes překryv platnosti PlatiOd a PlatiDo; oba zdroje nesou historická data.'
CLUSTER BY (company_id, kod_stav, plati_od)
TBLPROPERTIES (
    'delta.columnMapping.mode'   = 'name',
    'delta.enableChangeDataFeed' = 'true',
    'source.system'              = 'Plao',
    'source.object'              = 'StavPojSmlSalesCockpit',
    'load.pattern'               = 'Landing CSV, denně: StavPojSmlSalesCockpit_YYYYMMDD.csv'
);
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit SET TAGS ('description_en' = 'Mapping table of insurance contract statuses to the status names used in the Sales Cockpit. Uploaded by hand into the landing zone and joined to the KCC StavPojSml codelist on KodStav and CompanyID, for the current date between PlatiOd and PlatiDo.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit ALTER COLUMN company_id SET TAGS ('description_en' = 'Company identifier.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit ALTER COLUMN kod_stav SET TAGS ('description_en' = 'Insurance contract status code.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit ALTER COLUMN nazev_stav_sales_cockpit SET TAGS ('description_en' = 'Insurance contract status name as used in the Sales Cockpit.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit ALTER COLUMN __source_system SET TAGS ('description_en' = 'Source system.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit ALTER COLUMN __load_timestamp SET TAGS ('description_en' = 'Timestamp of when the record was added to the table.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit ALTER COLUMN __file_name SET TAGS ('description_en' = 'Name of the landing file the row was loaded from.');
ALTER TABLE dbx_cz_gcz_dev_czlake_bronze.man.stav_poj_sml_sales_cockpit ALTER COLUMN __file_path SET TAGS ('description_en' = 'Full path of the landing file the row was loaded from.');
